contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 newL1FeeScalar) public payable {
        uint256 before = c.l1FeeScalar(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setL1BlockValues(1, 2, 3, bytes32(uint256(4)), 5, bytes32(uint256(6)), 7, newL1FeeScalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.l1FeeScalar() == before);
    }

    receive() external payable {}
}

