// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint256 newL1FeeScalar) internal {
        uint256 before;
        try c.l1FeeScalar() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(1, 2, 3, bytes32(uint256(4)), 5, bytes32(uint256(6)), 7, newL1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.l1FeeScalar() == before);
    }

    function testFuzz_run(uint256 newL1FeeScalar) public {
        _run(newL1FeeScalar);
    }

    receive() external payable {}
}
